<?php require __DIR__."/vendor/autoload.php"; $app = require_once __DIR__."/bootstrap/app.php"; $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); $p = Illuminate\Support\Facades\DB::table("proyectos")->where("ejercicio_id", 17)->where("responsable_operativo_id", 444)->first(); echo "Proyecto SG ID: ".$p->proyecto_id."\n"; $acts = Illuminate\Support\Facades\DB::table("actividades_sustantivas")->where("proyecto_id", $p->proyecto_id)->get(); echo "Actividades: ".count($acts)."\n"; foreach($acts as $a) { echo $a->descripcion."\n"; } $accs = Illuminate\Support\Facades\DB::table("acciones_sustantivas")->where("proyecto_id", $p->proyecto_id)->get(); echo "Acciones: ".count($accs)."\n"; foreach($accs as $a) { echo $a->descripcion."\n"; }
